import pandas as pd

# Probe helper: bind only names used by scenarios.

# 1
try:
    # -93784567890123ns duration[ns][pyarrow] .dt.as_unit('s')
    ts = pd.Timestamp('-93784567890123')
except Exception as e:
    # If timestamp construction is wrong in this environment, record exception
    probe_exception("-93784567890123ns duration[ns][pyarrow] .dt.as_unit('s')", e)
else:
    try:
        # Create duration scalar/Timedelta via to_timedelta
        dur = pd.to_timedelta(-93784567890123, unit='ns')
        res = dur.as_unit('s')
        probe("-93784567890123ns duration[ns][pyarrow] .dt.as_unit('s')", res)
    except Exception as e:
        probe_exception("-93784567890123ns duration[ns][pyarrow] .dt.as_unit('s')", e)

# 2
try:
    # pd.Timestamp('1969-12-31 23:59:59.123456789') dtype timestamp[ns][pyarrow] .dt.as_unit('s')
    s = pd.Series([pd.Timestamp('1969-12-31 23:59:59.123456789')], dtype='timestamp[ns][pyarrow]')
    res = s.dt.as_unit('s')
    probe("pd.Timestamp('1969-12-31 23:59:59.123456789') dtype timestamp[ns][pyarrow] .dt.as_unit('s')", res)
except Exception as e:
    probe_exception("pd.Timestamp('1969-12-31 23:59:59.123456789') dtype timestamp[ns][pyarrow] .dt.as_unit('s')", e)

# 3
name3 = "values=[93784567890123, -93784567890123, None]; pd.to_timedelta(values, unit='ns').as_unit(from_unit).astype('duration[from_unit][pyarrow]').dt.as_unit(to_unit) for (from_unit,to_unit) in [(ns,s),(ns,ms),(ns,us),(us,s),(ms,s)]"
results3 = {}
try:
    values = [93784567890123, -93784567890123, None]
    for from_unit, to_unit in [('ns','s'),('ns','ms'),('ns','us'),('us','s'),('ms','s')]:
        tmp = pd.to_timedelta(values, unit='ns').as_unit(from_unit)
        tmp = tmp.astype(f'duration[{from_unit}][pyarrow]')
        tmp = tmp.dt.as_unit(to_unit)
        results3[(from_unit,to_unit)] = tmp
    probe(name3, results3)
except Exception as e:
    probe_exception(name3, e)

# 4
name4 = "pd.Series([pd.Timestamp('1969-12-31 23:59:59.123456789'), None], dtype='timestamp[ns][pyarrow]').dt.as_unit(to_unit) for to_unit in [s, ms, us]"
results4 = {}
try:
    ser = pd.Series([pd.Timestamp('1969-12-31 23:59:59.123456789'), None], dtype='timestamp[ns][pyarrow]')
    for to_unit in ['s','ms','us']:
        results4[to_unit] = ser.dt.as_unit(to_unit)
    probe(name4, results4)
except Exception as e:
    probe_exception(name4, e)

